let parsed: SrdvCityRow[] | null = null;

/** The full city list, parsed on first use. */
export function srdvCityRows(): SrdvCityRow[] {
  parsed ??= JSON.parse(CITY_ROWS_JSON) as SrdvCityRow[];

  return parsed;
}

let lookup: Map<string, string> | null = null;

/**
 * Lower-cased city name -> SRDV city code.
 *
 * SRDV already disambiguates the handful of repeated names inline ("Marnal
 * (Karnataka)"), so names are effectively unique; where one still repeats the
 * first row wins and the state-qualified form stays available for an exact
 * match.
 */
export function srdvCityCodeLookup(): ReadonlyMap<string, string> {
  if (lookup) {
    return lookup;
  }

  const map = new Map<string, string>();

  for (const [code, name, state] of srdvCityRows()) {
    const key = name.trim().toLowerCase();

    if (!map.has(key)) {
      map.set(key, code);
    }
    // Also indexed "city, state" so an ambiguous name can be pinned exactly.
    map.set(`${key}, ${state.trim().toLowerCase()}`, code);
  }

  lookup = map;

  return map;
}
